D3: seam double-inversion:
```js
test('D3: seam between two bricks — one bounce only, both bricks break', () => {
  const r1 = { x: 4, y: 76, w: 72, h: 20, alive: true }; // row 1
  const r2 = { x: 4, y: 104, w: 72, h: 20, alive: true }; // row 2
  const ball = { x: 40, y: 100, r: 7, vx: 0, vy: -400 }; // wedged in the seam, moving up
  const killed = bounceOffBricks(ball, [r1, r2]);
  assert.equal(killed.length, 2);
