// --- Brick collision (tested primitives) ----------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
export function collides(ball, brick) { ... unchanged ... }

// Resolves a single ball/brick overlap: picks the axis of smallest
// penetration (both axes on a corner), flips the matching velocity component
// and pushes the ball out until its edge is tangent to the brick face.
// Returns the ball. The ball is guaranteed to no longer overlap the brick.
export function resolveBrickCollision(ball, brick) {
  const overlapX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
  const overlapY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));
  if (overlapX <= 0 || overlapY <= 0) return ball; // no overlap (defensive)

  const hitLeft = ball.x < brick.x;
  const hitTop = ball.y < brick.y;
  const flipX = () => { ball.vx = hitLeft ? -Math.abs(ball.vx) : Math.abs(ball.vx); };
  const flipY = () => { ball.vy = hitTop ? -Math.abs(ball.vy) : Math.abs(ball.vy); };

  if (overlapX < overlapY) {
    flipX();
    ball.x += hitLeft ? -overlapX : overlapX;
  } else if (overlapY < overlapX) {
    flipY();
    ball.y += hitTop ? -overlapY : overlapY;
  } else {
    // corner: equal penetration on both axes
    flipX();
    flipY();
    ball.x += hitLeft ? -overlapX : overlapX;
    ball.y += hitTop ? -overlapY : overlapY;
  }
  return ball;
}
