// brick collisions, so a long step cannot tunnel through a brick or through
// the paddle band. Brick scoring follows the historical order (combo
// incremented before the score of each brick). Returns true if the ball was
// lost through the bottom.
export function advance(state, dt) {
  const { ball, bricks } = state;
  const dist = Math.hypot(ball.vx, ball.vy) * dt;
  const steps = Math.max(1, Math.ceil(dist / MAX_SUB_STEP));
  const subDt = dt / steps;
  for (let i = 0; i < steps; i++) {
